// W2 (NOTES_SPEC §12.6): thumbnail pipeline, created on the first request only (+0 on open and turn).
private var thumbs: PageThumbs? = null
/** Bumped on every REPAINT and reader colour change (thumbnail key; the generation stays). */
private var paintVersion = 0
/** Per-section quote/bookmark version (thumbnail key); sized on open, bumped only by annotation changes. */
private var decorVersion = IntArray(0)
