### RCA-2 ReaderActivity: implement `PageThumbsHost` (class header: `…, ReaderEndHost, PageThumbsHost`) and the source
```kotlin
override fun thumbTotal(): Int {
    val s = session ?: return 0
    // scrollModeActive(): does not exist yet — RC-A's own "scroll reading mode is on" flag (RC-S/RCA-S work).
    if (curLayout == null || page.frame == null || scrollModeActive()) return 0
    return s.counts.total()
}
override fun thumbCurrent(): Int = session?.counts?.globalPage(curSection, curPageIdx) ?: 0
override fun thumbAspect(): Float {
    val g = session?.generation?.geometry ?: return 0f
    return if (g.viewWidth > 0) g.viewHeight.toFloat() / g.viewWidth else 0f
}
override fun requestThumbs(first: Int, count: Int, widthPx: Int, heightPx: Int, progressive: Boolean, onBatch: (ThumbBatch) -> Unit) {
    val s = session ?: return
    val t = thumbs ?: PageThumbs(this, s, thumbSource, eink = DeviceClass.cached(this) == true).also { thumbs = it }
    t.request(first, count, widthPx, heightPx, progressive, onBatch)
}
/** Also gives the reader curSection ± 1 back when a thumbnail layout evicted them (PageThumbs.cancel). */
override fun cancelThumbs() { thumbs?.cancel() }

private val thumbSource = object : PageThumbs.Source {
    override fun decorFor(section: Int, layout: SectionLayout, pageIndex: Int): PageThumbs.Decor {
        val p = layout.pages.getOrNull(pageIndex) ?: return PageThumbs.Decor.NONE
        val hl = ArrayList<Highlight>()
        quotesBySection[section]?.let { addOverlapping(hl, it, p) } // persistent quotes only: no ownerHighlights
        val last = pageIndex == layout.pageCount - 1
        var marks = 0
        if (bookmarks.any { it.section == section && onPage(it.offset, p, last) }) marks = marks or ThumbCell.MARK_BOOKMARK
        if (hl.isNotEmpty()) marks = marks or ThumbCell.MARK_QUOTE
        val b = bookRef
        val qs = if (b != null) QuoteCache.get(b.id) else null
        if (qs != null && qs.any { it.section == section && it.note.isNotBlank() && it.end > p.start && it.start < p.end })
            marks = marks or ThumbCell.MARK_NOTE
        return PageThumbs.Decor(hl, marks)
    }
    override fun paintVersion(): Int = paintVersion
    override fun decorVersion(section: Int): Int = decorVersion.getOrElse(section) { 0 }
    override fun currentPage(): Int = thumbCurrent()
    override fun currentSection(): Int = if (session != null) curSection else -1
}
```
(`addOverlapping` and `onPage` are the existing private helpers; `isBookmarked(l, p)` only works for curSection, hence
the inline bookmark test. When RC-A's W1 `DecorDiff`/style-aware quote highlights replace `quotesBySection`, use the
same persistent quote map with `Highlight.style`.)

### EXN-1 ContentsDialog: four tabs
```kotlin
private val tabLabels = arrayOfNulls<TextView>(4)
private val tabBars = arrayOfNulls<View>(4)
private val tabViews = arrayOfNulls<View>(4)
/** The tabs' pagers (InkPager lists, the 썸네일 grid): the page keys move the selected one. */
private val pagers = arrayOfNulls<PageTarget>(4)
// The list tabs' own pager accesses (`pagers[1]?.list?.firstVisiblePosition`, `pagers[1]?.showRow(keep)`, same for
// [2]; base ContentsDialog.kt ~L593/631/659/698) no longer compile on PageTarget: use `(pagers[1] as? InkPager)`.
private var tab = initialTab.coerceIn(0, 3).let { if (it == 3 && !thumbsShown()) 0 else it }
private var thumbsTab: ThumbsTab? = null
/** 썸네일 is hidden in scroll mode (no pages). `hostInScrollMode()` does not exist yet: EX-N/RC-A need a host flag. */
private fun thumbsShown(): Boolean = host is PageThumbsHost && !hostInScrollMode()
```
- tab labels: `listOf("목차", "북마크", "인용문", "썸네일")`; each tab cell `lp(ctx.dp(90), WRAP_CONTENT)` (90 dp each,
  the row in a HorizontalScrollView only if < 360 dp), and the 썸네일 cell `visibility = GONE` when `!thumbsShown()`.
- disabled until a page is shown: when `!ThumbsTab.available(host)` the 썸네일 tab body is
  `ctx.emptyMessage("책을 여는 중입니다…")` (label grey, selecting it shows that message; nothing is requested).
- `select(i)`: loop `for (k in 0..3)`; insert BEFORE the existing `tab = i` (one e-ink update for switch + thumbnails):
```kotlin
if (tab == 3 && i != 3) thumbsTab?.stop() // leaving the tab: cancel + give the reader its neighbours back
if (i == 3 && ThumbsTab.available(host)) {
    val t = thumbsTab ?: ThumbsTab(host) { dialog.dismiss() }.also { thumbsTab = it; tabViews[3] = it.view; pagers[3] = it }
    tab = 3
    t.prepare(body.width, body.height) {
        if (tab != 3) return@prepare
        applyTabStyle(3); swapBody(t.view); shareAll.visibility = View.GONE
        onFirstShown?.invoke(); onFirstShown = null // see below
    }
    return // style + body swap happen in the callback (≤ 700 ms, one update)
}
```
- opened directly on tab 3 (⋮ 페이지 썸네일): `open()` must not `dialog.show()` before the grid is ready, or the empty
  dialog is a first update. Set `onFirstShown = { dialog.show(); PanelRegistry.dialog(ctx, dialog) }` before
  `select(tab)` when `tab == 3`, and call `dialog.show()` directly otherwise (the EpisodeWait pattern).
  (`applyTabStyle` / `swapBody` = the existing underline/typeface loop and `body.removeAllViews(); body.addView(v, …)`
  split out of `select`.)
- `dialog.setOnDismissListener { thumbsTab?.stop(); scope.cancel() }` (stop() calls `host.cancelThumbs()`, which also
  re-prefetches the reader's neighbours).
- page keys: the existing `pagers[tab]?.page(dir)` works unchanged with `PageTarget` (or `dialog.inkPagerKeys({ pagers[tab] }, …)`).
- "모두 공유" stays tab-2-only (`i == 2`).
- tab 3 uses no `InkPager`, so `pagers[3]` is set once and never nulled by the bookmark/quote reloads.
